import type { Request, Response, NextFunction } from 'express';
import { logger } from './logger.js';

const STATIC_TOKEN = process.env.MCP_BEARER_TOKEN;

export async function authMiddleware(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  // Skip auth for public routes
  const publicPaths = [
    '/.well-known/oauth-protected-resource',
    '/register',
    '/oauth/authorize',
    '/oauth/token',
    '/oauth/callback',
    '/health',
    '/mcp-metadata',
  ];
  if (publicPaths.includes(req.path) || req.method === 'OPTIONS') {
    next();
    return;
  }

  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    res.status(401).json({
      error: 'unauthorized',
      error_description: 'Missing or invalid Bearer token',
    });
    return;
  }

  const token = authHeader.slice(7);

  // Mode 1: static bearer token (for MeetStream ↔ ngrok proxy)
  if (STATIC_TOKEN) {
    if (token !== STATIC_TOKEN) {
      logger.warn('Static bearer token mismatch');
      res.status(401).json({ error: 'unauthorized', error_description: 'Invalid Bearer token' });
      return;
    }
    (req as any).scopes = ['gmail:read'];
    next();
    return;
  }

  // Mode 2: Scalekit OAuth introspection
  try {
    const { getScalekitClient } = await import('./scalekit.js');
    const sk = getScalekitClient();
    const introspection = await (sk as any).auth.introspectToken(token);
    if (!introspection.active) {
      res.status(401).json({ error: 'unauthorized', error_description: 'Token is not active' });
      return;
    }
    (req as any).tokenPayload = introspection;
    (req as any).scopes = (introspection.scope ?? '').split(' ');
    next();
  } catch (err) {
    logger.error('Token validation failed', { err });
    res.status(401).json({
      error: 'unauthorized',
      error_description: 'Token validation failed',
    });
  }
}

export function checkScope(scope: string) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const scopes: string[] = (req as any).scopes ?? [];
    if (!scopes.includes(scope)) {
      res.status(403).json({
        error: 'insufficient_scope',
        error_description: `Required scope: ${scope}`,
      });
      return;
    }
    next();
  };
}

/**
 * Checks whether a user's scope list satisfies all required scopes for a tool.
 */
export function validateToolScopes(userScopes: string[], requiredScopes: string[]): boolean {
  return requiredScopes.every((s) => userScopes.includes(s));
}

import { getScalekitClient } from './scalekit.js';
import { logger } from './logger.js';

const GMAIL_CONNECTION = 'gmail';

export async function ensureGmailConnected(
  identifier: string
): Promise<{ connected: boolean; authLink?: string }> {
  const sk = getScalekitClient();
  try {
    const resp = await (sk as any).actions.getOrCreateConnectedAccount({
      connectionName: GMAIL_CONNECTION,
      identifier,
    });
    const account = resp.connectedAccount ?? resp.connected_account;
    if (account?.status === 'ACTIVE') {
      logger.info('Gmail connected account active', { identifier, accountId: account.id });
      return { connected: true };
    }
    const linkResp = await (sk as any).actions.getAuthorizationLink({
      connectionName: GMAIL_CONNECTION,
      identifier,
    });
    return { connected: false, authLink: linkResp.link };
  } catch (err) {
    logger.error('Failed to get connected account', { err });
    throw err;
  }
}

export async function executeGmailTool(
  toolName: string,
  toolInput: Record<string, unknown>,
  identifier: string
): Promise<unknown> {
  const sk = getScalekitClient();
  const result = await (sk as any).actions.executeTool({
    toolName,
    identifier,
    toolInput,
  });
  return result.data ?? result;
}

/**
 * Execute a Scalekit tool for a given identifier.
 * Argument order: (identifier, toolName, toolInput) — matches gmail.ts call sites.
 */
export async function executeScalekitTool(
  identifier: string | undefined,
  toolName: string,
  toolInput: Record<string, unknown>
): Promise<unknown> {
  return executeGmailTool(toolName, toolInput, identifier ?? '');
}

import ScalekitClient from '@scalekit-sdk/node';
import { config } from '../config/config.js';

let _client: ScalekitClient | null = null;

export function getScalekitClient(): ScalekitClient {
  if (!_client) {
    _client = new ScalekitClient(
      config.skEnvUrl,
      config.skClientId,
      config.skClientSecret,
    );
  }
  return _client;
}

import crypto from 'node:crypto';
import type { Express, Request, Response } from 'express';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { logger } from './logger.js';

const UPSTREAM_URL = process.env.MCP_UPSTREAM_URL?.replace(/\/$/, '');

/**
 * Shared store mapping session IDs to user context objects.
 * Used by tool handlers to look up the authenticated user.
 */
export interface UserContext {
  user?: {
    id: string;
    scopes?: string[];
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

export const userContextStore = new Map<string, UserContext>();

/**
 * Proxy an authenticated request to the upstream ngrok MCP server.
 * Strips Authorization header — upstream has no auth.
 */
async function proxyToUpstream(req: Request, res: Response): Promise<void> {
  if (!UPSTREAM_URL) {
    res.status(502).json({ error: 'No upstream MCP server configured (set MCP_UPSTREAM_URL)' });
    return;
  }

  const upstreamUrl = `${UPSTREAM_URL}/`;
  const forwardedHeaders: Record<string, string> = {
    'content-type': (req.headers['content-type'] as string) ?? 'application/json',
    'accept': (req.headers['accept'] as string) ?? 'application/json, text/event-stream',
  };

  // Preserve MCP session ID for stateful connections
  if (req.headers['mcp-session-id']) {
    forwardedHeaders['mcp-session-id'] = req.headers['mcp-session-id'] as string;
  }

  logger.info('Proxying to upstream MCP server', { method: req.method, upstreamUrl });

  try {
    const upstream = await fetch(upstreamUrl, {
      method: req.method,
      headers: forwardedHeaders,
      body:
        req.method !== 'GET' && req.method !== 'HEAD'
          ? JSON.stringify(req.body)
          : undefined,
    });

    res.status(upstream.status);

    const skipHeaders = new Set(['transfer-encoding', 'connection', 'keep-alive', 'upgrade']);
    upstream.headers.forEach((value, key) => {
      if (!skipHeaders.has(key.toLowerCase())) res.setHeader(key, value);
    });

    const contentType = upstream.headers.get('content-type') ?? '';

    if (contentType.includes('text/event-stream')) {
      res.setHeader('Content-Type', 'text/event-stream');
      res.setHeader('Cache-Control', 'no-cache');
      res.setHeader('Connection', 'keep-alive');
      res.flushHeaders();

      const reader = upstream.body?.getReader();
      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          res.write(value);
        }
      }
      res.end();
    } else {
      const body = await upstream.text();
      res.send(body);
    }
  } catch (err) {
    logger.error('Upstream proxy error', { err });
    res.status(502).json({ error: 'Upstream MCP server unreachable', detail: String(err) });
  }
}

/**
 * Sets up MCP transport routes on the Express app.
 *
 * Proxy mode  (MCP_UPSTREAM_URL set):  forward to upstream ngrok server
 * Direct mode (no MCP_UPSTREAM_URL):   handle locally with StreamableHTTPServerTransport
 */
export function setupTransportRoutes(app: Express, mcpServer: McpServer): void {
  if (UPSTREAM_URL) {
    logger.info('Transport: PROXY mode', { upstreamUrl: UPSTREAM_URL });

    app.all('/', async (req: Request, res: Response) => {
      await proxyToUpstream(req, res);
    });
  } else {
    logger.info('Transport: DIRECT mode (local StreamableHTTP)');

    app.post('/', async (req: Request, res: Response) => {
      try {
        const transport = new StreamableHTTPServerTransport({
          sessionIdGenerator: () => crypto.randomUUID(),
        });
        await mcpServer.connect(transport);
        await transport.handleRequest(req, res, req.body);
      } catch (err) {
        logger.error('MCP transport error', { err });
        if (!res.headersSent) {
          res.status(500).json({ error: 'MCP transport error', detail: String(err) });
        }
      }
    });

    // SSE GET for streaming transports
    app.get('/', async (req: Request, res: Response) => {
      try {
        const transport = new StreamableHTTPServerTransport({
          sessionIdGenerator: () => crypto.randomUUID(),
        });
        await mcpServer.connect(transport);
        await transport.handleRequest(req, res, req.body);
      } catch (err) {
        logger.error('MCP SSE transport error', { err });
        if (!res.headersSent) {
          res.status(500).json({ error: 'MCP SSE error', detail: String(err) });
        }
      }
    });

    // DELETE for session teardown
    app.delete('/', async (req: Request, res: Response) => {
      try {
        const transport = new StreamableHTTPServerTransport({
          sessionIdGenerator: () => crypto.randomUUID(),
        });
        await mcpServer.connect(transport);
        await transport.handleRequest(req, res, req.body);
      } catch (err) {
        logger.error('MCP DELETE transport error', { err });
        if (!res.headersSent) {
          res.status(500).json({ error: 'MCP session teardown error', detail: String(err) });
        }
      }
    });
  }
}
